#!/data/data/com.termux/files/usr/bin/bash
# HAYU - Efek SVGA: Efek Masuk, Kendaraan, Bingkai (room + profil)
#  1. Jenis aset baru "Efek Masuk" (SVGA Manager, Toko, Hiasan Saya -> tab "Efek Masuk" sekarang berfungsi)
#  2. Room: saat masuk, efek masuk (yang dipasang, atau bawaan SVIP) lalu kendaraan diputar berurutan
#     dan diumumkan ke semua orang di room (efek diputar antre, tidak saling memotong)
#  3. Room: bingkai kursi sekarang juga memakai bingkai bawaan VIP/SVIP (dulu hanya yang dipasang di Hiasan)
#  4. Kalau aset online (VIP/SVIP) atau bingkai gagal dimuat, muncul pesan berisi alamat yang gagal
#     -> berguna untuk mencari kenapa efek tidak tampil
# Menimpa: SvgaCatalog, ShopUtil, TokoActivity, HiasanActivity, SvgaPlayer, RoomActivity (backup otomatis)
# Jalankan di root repo:  bash pasang-efek-svga.sh
set -e
cd "${REPO:-$PWD}"
D="app/src/main/java/com/hayu/app"
for f in SvgaCatalog ShopUtil TokoActivity HiasanActivity SvgaPlayer RoomActivity VipAssets; do
  [ -f "$D/$f.kt" ] || { echo "❌ $D/$f.kt tidak ditemukan. Jalankan di root repo Hayu-android"; exit 1; }
done
grep -q "fun url(" "$D/VipAssets.kt" || { echo "❌ VipAssets.kt belum versi online. Jalankan dulu: bash pasang-aset-remote.sh"; exit 1; }

T="$(mktemp -d)"
cat > "$T/b.b64" <<'B64_EOF'

B64_EOF
base64 -d "$T/b.b64" > "$T/b.tgz"
mkdir "$T/new" && tar xzf "$T/b.tgz" -C "$T/new"

BK="$HOME/.hayu-backup-efek-$(date +%H%M%S)"
mkdir -p "$BK"
for f in SvgaCatalog ShopUtil TokoActivity HiasanActivity SvgaPlayer RoomActivity adapter/RoomMessageAdapter; do
  mkdir -p "$BK/$D/$(dirname "$f")"; cp "$D/$f.kt" "$BK/$D/$f.kt"
done
for f in SvgaCatalog ShopUtil TokoActivity HiasanActivity SvgaPlayer RoomActivity; do
  cp "$T/new/$D/$f.kt" "$D/$f.kt"
  echo "  dipasang  $D/$f.kt"
done
rm -rf "$T"

# chat: pengumuman efek masuk tampil sebagai pesan sistem
A="$D/adapter/RoomMessageAdapter.kt"
if grep -q '"✨ MASUK"' "$A"; then
  echo "  ok        $A"
else
  sed -i 's#"🚗 MASUK", #"🚗 MASUK", "✨ MASUK", #' "$A"
  grep -q '"✨ MASUK"' "$A" && echo "  DIPERBAIKI $A" || echo "  ⚠️ $A: daftar SPECIAL_NAMES tidak ditemukan (pesan efek masuk tetap tampil, hanya gayanya biasa)"
fi

echo ""
echo "✅ Selesai. Backup: $BK"
echo "Lanjut: git add -A && git commit -m 'efek masuk + bingkai/kendaraan di room' && git push"
echo ""
echo "Cara pakai Efek Masuk:"
echo "  1) Developer: SVGA Manager -> pilih jenis '🏅 Efek Masuk' -> unggah .svga, atur harga/hari"
echo "  2) User: Toko -> tab 'Efek Masuk' -> beli; Hiasan Saya -> tab 'Efek Masuk' -> pasang"
echo "  3) Masuk room -> efek diputar & diumumkan. SVIP tanpa efek pasangan memakai efek bawaan SVIP."
